    creditGauge: () => `${[[R, 180, 225], ["#F08A24", 225, 270], [A, 270, 315], [G, 315, 360]].map(([c, a1, a2]) => { const p = (a) => [160 + 100 * Math.cos(a * Math.PI / 180), 160 + 100 * Math.sin(a * Math.PI / 180)]; const [x1, y1] = p(a1), [x2, y2] = p(a2); return `<path d="M${x1.toFixed(1)} ${y1.toFixed(1)} A100 100 0 0 1 ${x2.toFixed(1)} ${y2.toFixed(1)}" stroke="${c}" stroke-width="22" fill="none"/>`; }).join("")}<path d="M160 160 L214 104" stroke="${K}" stroke-width="6" stroke-linecap="round"/><circle cx="160" cy="160" r="10" fill="${K}"/>${tx(60, 186, "300", { s: 14, w: 700 })}${tx(260, 186, "850", { s: 14, w: 700 })}${tx(128, 140, "720", { s: 30, w: 800, f: "Archivo, sans-serif" })}`,
